+    // Buffers for packing panels (size BLOCK x BLOCK)
+    alignas(32) float packedA[ BLOCK * BLOCK ];
+    alignas(32) float packedB[ BLOCK * BLOCK ];
+
+    for (int i0 = 0; i0 < n; i0 += BLOCK) {
+        int i_end = (i0 + BLOCK < n) ? i0 + BLOCK : n;
+        int i_len = i_end - i0;
+
+        for (int k0 = 0; k0 < n; k0 += BLOCK) {
+            int k_end = (k0 + BLOCK < n) ? k0 + BLOCK : n;
+            int k_len = k_end - k0;
