+            // Pack A panel (i_len x k_len)
+            for (int ii = 0; ii < i_len; ++ii) {
+                const float* a_row = A + (i0 + ii) * n + k0;
+                for (int kk = 0; kk < k_len; ++kk) {
+                    packedA[ii * k_len + kk] = a_row[kk];
+                }
+            }
+
+            for (int j0 = 0; j0 < n; j0 += BLOCK) {
+                int j_end = (j0 + BLOCK < n) ? j0 + BLOCK : n;
+                int j_len = j_end - j0;
+
+                // Pack B panel (k_len x j_len)
+                for (int kk = 0; kk < k_len; ++kk) {
+                    const float* b_row = B + (k0 + kk) * n + j0;
+                    for (int jj = 0; jj < j_len; ++jj) {
+                        packedB[kk * j_len + jj] = b_row[jj];
+                    }
+                }
